def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    mask = objective[:, :, None] < objective[:, None, :]
    b_idx, loser_idx, winner_idx = mask.nonzero(as_tuple=True)
    weight = objective[b_idx, winner_idx] - objective[b_idx, loser_idx]
    return PrefBatch(mode='pairwise', pair_idx=(b_idx, loser_idx, winner_idx), weight=weight, meta={'builder': 'all_pairs_weighted_diff'})
